WITH lines AS (SELECT id, plan, effective_from, currency, EXPLODE(tier_limits) AS tier_value FROM price_tiers), filtered AS (SELECT id, plan, effective_from, currency, tier_value, TRIM(currency) AS clean_currency, LOWER(currency) AS currency_lower FROM lines WHERE plan <> 'starter'), enriched AS (SELECT id, plan, effective_from, currency, tier_value, clean_currency, currency_lower, MIN(tier_value) OVER (PARTITION BY plan) AS plan_min_tier_value, STDDEV_SAMP(tier_value) OVER (PARTITION BY currency, plan) AS currency_stddev_samp_tier_value FROM filtered), scored AS (SELECT *, MIN(currency_stddev_samp_tier_value) OVER (PARTITION BY currency) AS currency_min_currency_stddev_samp_tier_value, CUME_DIST() OVER (PARTITION BY currency ORDER BY currency_stddev_samp_tier_value) AS currency_stddev_samp_tier_value_cume_dist FROM enriched), with_windows AS (SELECT *, DENSE_RANK() OVER (PARTITION BY plan ORDER BY tier_value) AS tier_value_dense_rank, SUM(currency_min_currency_stddev_samp_tier_value) OVER (PARTITION BY currency, plan) AS currency_sum_currency_min_currency_stddev_samp_tier_value FROM scored), scored_price_tiers AS (SELECT *, AVG(tier_value_dense_rank) OVER (PARTITION BY currency) AS currency_avg_tier_value_dense_rank, MIN(tier_value_dense_rank) OVER w_ordered AS currency_min_tier_value_dense_rank, MAX(currency_sum_currency_min_currency_stddev_samp_tier_value) OVER w_ordered AS currency_max_currency_sum_currency_min_currency_stddev_samp_tier_value FROM with_windows WINDOW w_ordered AS (PARTITION BY currency, plan)) SELECT id, plan, effective_from, currency, tier_value, clean_currency, currency_lower, plan_min_tier_value, currency_stddev_samp_tier_value, CASE WHEN currency RLIKE '^(USD|THB)$' THEN 'GROUP_B' WHEN currency RLIKE '^(EUR)$' THEN 'OTHER_ZONE' ELSE 'EXTENDED' END AS currency_zone FROM scored_price_tiers
